entries[257284] = { ["name"] = "Mal des Jägers", ["text"] = "60 Meter Reichweite\nSofort\nBelegt das Ziel mit dem 'Mal des Jägers', sodass es immer vom Jäger gesehen und aufgespürt werden kann.\n\n'Mal des Jägers' erhöht sämtlichen Schaden, den Ihr Zielen über 80% Gesundheit zufügt, um 5%. Es kann immer nur eine Schadenserhöhung durch 'Mal des Jägers' auf ein Ziel angewendet werden.\n\n'Mal des Jägers' kann immer nur auf ein Ziel zurzeit angewendet werden. Beim Einsatz von 'Mal des Jägers' im Kampf hat die Fähigkeit eine Abklingzeit von 20 Sek." }
entries[257286] = { ["name"] = "Wütender Sturm", ["text"] = "100 Meter Reichweite\nSofort\nEure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an." }
