entries[257619] = { ["name"] = "Geschenk der Lebensbinderin", ["text"] = "Unbegrenzte Reichweite\nWirken in 8 sek.\nEonar erschafft das Geschenk der Lebensbinderin, einen lebensspendenden Baum, der hervorsprießt, um die Spielercharaktere zu retten. Das Geschenk der Lebensbinderin wird abhängig von der Schlachtzugsgröße mit mehreren Aufladungen von 'Lebensspendende Wurzeln' erschaffen. Spielercharaktere können das Geschenk der Lebensbinderin heilen.\n\nWährend das Geschenk der Lebensbinderin lebt, können Spielercharaktere während des Kampfes gegen Argus nach ihrem Tod beliebig ihren Geist freilassen, um als Geist zum Ort der Begegnung zurückzukehren. Wenn sich ein Spielercharakter als Geist dem Baum nähert, wird er wiederbelebt und eine Aufladung von 'Lebensspendende Wurzeln' wird entfernt. Sobald die Aufladungen von 'Lebensspendende Wurzeln' verbraucht sind, ruft eine Wiederbelebung durch das Geschenk der Lebensbinderin bei ihr einen Stapel 'Verdorrte Wurzeln' hervor." }
entries[257620] = { ["name"] = "Mehrfachschuss", ["text"] = "30 Fokus 40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Geschosssalve ab, die Euer aktuelles Ziel sowie alle Gegner innerhalb von 10 Metern trifft und ihnen (50.76% der Angriffskraft) körperlichen Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Tödliche Schüsse : 'Mehrfachschuss' hat eine Chance von 30%, die Abklingzeit von 'Schnellfeuer' um 5.0 Sek. zu verringern ]" }
entries[257621] = { ["name"] = "Gekonnte Schüsse", ["text"] = "Wenn 'Mehrfachschuss' 3 oder mehr Ziele trifft, prallt Euer nächster Einsatz von 'Gezielter Schuss' oder 'Schnellfeuer' auf bis zu 5 zusätzliche Ziele ab und fügt ihnen 60% des normalen Schadens zu." }
