entries[257671] = { ["name"] = "Golganneths donnernde Wut", ["text"] = "100 Meter Reichweite\nSofort\nEure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an." }
entries[257673] = { ["name"] = "Lebensenergie", ["text"] = "Sofort\nEonars Lebensenergie steigt mit jedem bezwungenen Legionsinvasor. Beim Erreichen von 100 Lebensenergie greift sie die Paraxis sowie alle Streitkräfte der Legion mit 'Lebenskraft' an.\n\nLebenskraft Unbegrenzte Reichweite Wirken in 3 Sek. Eonar sammelt ihre Lebenskraft an und überzieht die Paraxis mit Naturschaden. Zusätzlich fegt eine Schockwelle über die Zone hinweg, die allen gegnerischen Eindringlingen Schaden zufügt." }
entries[257674] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 2 sek. Abklingzeit\nVerbirgt Euch bis zum Abbruch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden.\n\nWährend Ihr verborgen seid, regeneriert Ihr alle 1 Sek. 2 Gesundheit." }
